class Solution {
  public int maxBalancedSubarray(int[] nums) {
    java.util.HashMap<Long, Integer> first = new java.util.HashMap<>();
    int n = nums.length, xor = 0, diff = 0, best = 0;
    first.put(0L << 18 | 131072, -1);
    for (int i = 0; i < n; i++) {
      xor ^= nums[i];
      diff += (nums[i] & 1) == 0 ? 1 : -1;
      long key = ((long) xor << 18) | (diff + 131072);
      Integer prev = first.putIfAbsent(key, i);
      if (prev != null) best = Math.max(best, i - prev);
    }
    return best;
  }
}
